// Generated by canonical agentfile.Parse at bc1fc4a7 from a synthetic charter;
// it is neither the final edited source nor passing target-example evidence.
func agentFileFixture(t *testing.T) ([]byte, agentFileProjection) {
	t.Helper()
	raw, err := os.ReadFile("testdata/agent-file-projection.json")
	if err != nil {
		t.Fatal(err)
	}
	p, err := decodeAgentFileProjection(raw)
	if err != nil {
		t.Fatal(err)
	}
	return raw, p
}
func agentFileInput(t *testing.T, raw []byte) string {
	t.Helper()
	path := filepath.Join(privateTempDir(t), "projection.json")
	if err := os.WriteFile(path, raw, 0600); err != nil {
		t.Fatal(err)
	}
	return path
}
func agentFileJSON(t *testing.T, v any) []byte {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}
func agentFilePrepare(t *testing.T) (string, agentFileSummary) {
	t.Helper()
	raw, _ := agentFileFixture(t)
	data := privateTempDir(t)
	summary, err := prepareAgentFile(data, agentFileInput(t, raw), "target-model")
	if err != nil {
		t.Fatal(err)
	}
	return data, summary
}

func TestAgentFilePrepareInspectAndNoExecution(t *testing.T) {
	raw, p := agentFileFixture(t)
	data := privateTempDir(t)
	var out bytes.Buffer
	if err := runCLI(t.Context(), []string{"agent-file-prepare", "--data", data, "--projection", agentFileInput(t, raw), "--target-model", "target-model"}, &out, io.Discard); err != nil {
		t.Fatal(err)
	}
	var summary agentFileSummary
	if err := json.Unmarshal(out.Bytes(), &summary); err != nil {
		t.Fatal(err)
	}
	profile, again, err := loadAgentFile(data)
	if err != nil {
		t.Fatal(err)
	}
	if summary != again || summary.AuthoredModel != "source-model" || summary.TargetModel != "target-model" || summary.ProofKind != "different-model-source-file" || summary.TargetExamples != "not-run" || summary.SourceSHA256 != p.SourceSHA256 || summary.ParserCommit != p.ParserCommit || summary.ExamplesSHA256 != p.ExamplesSHA256 {
		t.Fatalf("wrong identity/claim: %+v", summary)
	}
	stored, err := os.ReadFile(filepath.Join(data, "agent-file.json"))
	if err != nil {
		t.Fatal(err)
	}
	if summary.ProfileSHA256 != agentFileDigest(stored) || summary.Route != "release-writer-file-v1-"+digestBytes(stored) {
		t.Fatal("route doesn't bind the full file")
	}
	var preserved agentFileProjection
	if err := json.Unmarshal(profile.Projection, &preserved); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(p.Source, preserved.Source) || p.Instructions != preserved.Instructions || !bytes.Equal(p.Examples, preserved.Examples) {
		t.Fatal("projection bytes changed")
	}
	for _, secret := range []string{p.Instructions, "Fictional change", data, "mentions-csv", "benefit"} {
		if strings.Contains(out.String(), secret) {
			t.Fatal("summary disclosed content or path")
		}
	}
	out.Reset()
	if err := runCLI(t.Context(), []string{"agent-file-inspect", "--data", data}, &out, io.Discard); err != nil {
		t.Fatal(err)
	}
	var inspected agentFileSummary
	if err := json.Unmarshal(out.Bytes(), &inspected); err != nil || inspected != summary {
		t.Fatalf("inspection: %v", err)
	}
	entries, err := os.ReadDir(data)
	if err != nil || len(entries) != 2 {
		t.Fatalf("unexpected execution/state: %v %v", entries, err)
	}
	for _, name := range []string{"agent-file.json", "scenario.json"} {
		st, err := os.Stat(filepath.Join(data, name))
		if err != nil || st.Mode().Perm() != 0600 {
			t.Fatalf("private file: %v", err)
		}
	}
	// Existing fixture roles must not adopt the new profile's data.
	for _, scenario := range []string{"v1", "v2"} {
		if err := checkScenario(data, scenario); err == nil {
			t.Fatalf("%s adopted agent-file state", scenario)
		}
	}
}

func TestAgentFilePinnedParserConformanceAndOpaqueExamples(t *testing.T) {
	_, p := agentFileFixture(t)
	if p.ParserCommit != "bc1fc4a7c0ebeac37ef340c7928ed80e844f7643" || !strings.HasSuffix(p.Instructions, "\n\n") || strings.Contains(p.Instructions, "## Examples") {
		t.Fatal("canonical projection drift")
	}
	if !bytes.Contains(p.Examples, []byte(`"llmJudge"`)) || !bytes.Contains(p.Examples, []byte(`"judgeModel":"source-model"`)) {
		t.Fatal("assertions lost")
	}
	p.Source = []byte(strings.ReplaceAll(string(p.Source), "\n", "\r\n"))
	p.SourceSHA256 = agentFileDigest(p.Source)
	if _, err := decodeAgentFileProjection(agentFileJSON(t, p)); err != nil {
		t.Fatalf("CRLF exact-byte revision with normalized instructions: %v", err)
	}
	// Opaque examples retain unknown/case-variant fields: no second assertion parser.
	p.Examples = json.RawMessage(`[ {"ID":"operator-owned","Assertions":[{"newAssertion":true}]} ]`)
	p.ExamplesSHA256 = agentFileDigest(p.Examples)
	raw := agentFileJSON(t, p)
	// Marshal compacts RawMessage; bind the exact serialized example bytes.
	var compact agentFileProjection
	if err := json.Unmarshal(raw, &compact); err != nil {
		t.Fatal(err)
	}
	compact.ExamplesSHA256 = agentFileDigest(compact.Examples)
	parsed, err := decodeAgentFileProjection(agentFileJSON(t, compact))
	if err != nil || !bytes.Equal(parsed.Examples, compact.Examples) {
		t.Fatalf("opaque bytes not retained: %v", err)
	}
}

func TestAgentFileWhitespacePreservedAndIdentity(t *testing.T) {
	raw, p := agentFileFixture(t)
	var pretty bytes.Buffer
	if err := json.Indent(&pretty, p.Examples, "", "  "); err != nil {
		t.Fatal(err)
	}
	changed := bytes.Replace(raw, p.Examples, pretty.Bytes(), 1)
	changed = bytes.Replace(changed, []byte(p.ExamplesSHA256), []byte(agentFileDigest(pretty.Bytes())), 1)
	data := privateTempDir(t)
	summary, err := prepareAgentFile(data, agentFileInput(t, changed), "target-model")
	if err != nil {
		t.Fatal(err)
	}
	profile, _, err := loadAgentFile(data)
	if err != nil || !bytes.Equal(profile.Projection, changed) {
		t.Fatalf("exact projection bytes lost: %v", err)
	}
	_, original := agentFilePrepare(t)
	if summary.Route == original.Route || summary.ExamplesSHA256 == original.ExamplesSHA256 || summary.SourceSHA256 != original.SourceSHA256 {
		t.Fatal("whitespace identity was normalized or source identity changed")
	}
}

func TestAgentFileExclusiveWriterRefusesIdentical(t *testing.T) {
	path := filepath.Join(privateTempDir(t), "profile.json")
	raw := []byte("original")
	if err := writeAgentFileOnce(path, raw); err != nil {
		t.Fatal(err)
	}
	for _, next := range [][]byte{raw, []byte("changed")} {
		if err := writeAgentFileOnce(path, next); err == nil {
			t.Fatal("exclusive write adopted or overwrote existing bytes")
		}
	}
	after, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(raw, after) {
		t.Fatal("exclusive failure changed retained state")
	}
}

func TestAgentFileProjectionRefusals(t *testing.T) {
	_, base := agentFileFixture(t)
	cases := map[string]func(*agentFileProjection){
		"version":           func(p *agentFileProjection) { p.Version = 2 },
		"parser":            func(p *agentFileProjection) { p.ParserCommit = strings.Repeat("a", 40) },
		"agent":             func(p *agentFileProjection) { p.AgentID = "another-agent" },
		"source-hash":       func(p *agentFileProjection) { p.SourceSHA256 = agentFileDigest([]byte("changed")) },
		"instructions-hash": func(p *agentFileProjection) { p.InstructionsSHA256 = "" },
		"examples-hash":     func(p *agentFileProjection) { p.ExamplesSHA256 = "" },
		"model-auto":        func(p *agentFileProjection) { p.AuthoredModel = "auto" },
		"model-url":         func(p *agentFileProjection) { p.AuthoredModel = "https://model.invalid" },
		"instructions-not-source": func(p *agentFileProjection) {
			p.Instructions = "changed\n"
			p.InstructionsSHA256 = agentFileDigest([]byte(p.Instructions))
		},
		"instructions-entire-file": func(p *agentFileProjection) {
			p.Instructions = string(p.Source)
			p.InstructionsSHA256 = agentFileDigest([]byte(p.Instructions))
		},
		"instructions-empty":  func(p *agentFileProjection) { p.Instructions = ""; p.InstructionsSHA256 = agentFileDigest(nil) },
		"invalid-utf8-source": func(p *agentFileProjection) { p.Source = []byte{255}; p.SourceSHA256 = agentFileDigest(p.Source) },
		"oversize-source": func(p *agentFileProjection) {
			p.Source = bytes.Repeat([]byte("a"), 256*1024+1)
			p.SourceSHA256 = agentFileDigest(p.Source)
		},
		"examples-null": func(p *agentFileProjection) {
			p.Examples = json.RawMessage("null")
			p.ExamplesSHA256 = agentFileDigest(p.Examples)
		},
		"examples-object": func(p *agentFileProjection) {
			p.Examples = json.RawMessage(`{}`)
			p.ExamplesSHA256 = agentFileDigest(p.Examples)
		},
		"examples-empty": func(p *agentFileProjection) {
			p.Examples = json.RawMessage(`[]`)
			p.ExamplesSHA256 = agentFileDigest(p.Examples)
		},
	}
	for name, change := range cases {
		t.Run(name, func(t *testing.T) {
			p := base
			change(&p)
			_, err := decodeAgentFileProjection(agentFileJSON(t, p))
			if err == nil {
				t.Fatal("invalid projection accepted")
			}
			if strings.Contains(err.Error(), "Fictional") {
				t.Fatal("payload error")
			}
		})
	}
	raw, _ := agentFileFixture(t)
	for name, bad := range map[string][]byte{
		"unknown":          append([]byte(`{"unknown":1,`), raw[1:]...),
		"case":             bytes.Replace(raw, []byte(`"version":`), []byte(`"Version":`), 1),
		"duplicate":        append([]byte(`{"version":1,`), raw[1:]...),
		"nested-duplicate": bytes.Replace(raw, []byte(`"id":"csv"`), []byte(`"id":"csv","id":"x"`), 1),
		"trailing":         append(append([]byte(nil), raw...), []byte(`{}`)...),
		"raw-limit":        bytes.Repeat([]byte(" "), (1<<20)+1),
	} {
		t.Run(name, func(t *testing.T) {
			if _, err := decodeAgentFileProjection(bad); err == nil {
				t.Fatal("ambiguous or oversized JSON accepted")
			}
		})
	}
}

func TestAgentFileFreshPrivateStateOnly(t *testing.T) {
	raw, _ := agentFileFixture(t)
	input := agentFileInput(t, raw)
	for _, target := range []string{"", "source-model", "auto", "https://model.invalid", " target-model"} {
		data := privateTempDir(t)
		if _, err := prepareAgentFile(data, input, target); err == nil {
			t.Fatalf("invalid target accepted: %q", target)
		}
		entries, _ := os.ReadDir(data)
		if len(entries) != 0 {
			t.Fatal("failed validation created state")
		}
	}
	data, summary := agentFilePrepare(t)
	original, _ := os.ReadFile(filepath.Join(data, "agent-file.json"))
	if _, err := prepareAgentFile(data, input, summary.TargetModel); err == nil {
		t.Fatal("identical existing profile adopted")
	}
	after, _ := os.ReadFile(filepath.Join(data, "agent-file.json"))
	if !bytes.Equal(original, after) {
		t.Fatal("existing profile changed")
	}
	for _, name := range []string{"journal.db", "scenario.json", "unrelated"} {
		dir := privateTempDir(t)
		if err := os.WriteFile(filepath.Join(dir, name), []byte("retained"), 0600); err != nil {
			t.Fatal(err)
		}
		if _, err := prepareAgentFile(dir, input, "target-model"); err == nil {
			t.Fatal("nonempty state adopted")
		}
	}
	missing := filepath.Join(privateTempDir(t), "missing")
	if _, err := prepareAgentFile(missing, input, "target-model"); err == nil {
		t.Fatal("missing directory created")
	}
	if _, err := os.Stat(missing); !os.IsNotExist(err) {
		t.Fatal("failed prepare created directory")
	}
	dir := privateTempDir(t)
	if err := os.Chmod(dir, 0755); err != nil {
		t.Fatal(err)
	}
	if _, err := prepareAgentFile(dir, input, "target-model"); err == nil {
		t.Fatal("nonprivate directory accepted")
	}
	if st, _ := os.Stat(dir); st.Mode().Perm() != 0755 {
		t.Fatal("permissions silently repaired")
	}
}

func TestAgentFileReadRefusesUnsafePaths(t *testing.T) {
	raw, _ := agentFileFixture(t)
	for _, kind := range []string{"symlink", "parent-symlink", "fifo", "permissions", "directory", "relative"} {
		t.Run(kind, func(t *testing.T) {
			input := agentFileInput(t, raw)
			switch kind {
			case "symlink":
				p := filepath.Join(privateTempDir(t), "link")
				if err := os.Symlink(input, p); err != nil {
					t.Fatal(err)
				}
				input = p
			case "parent-symlink":
				p := filepath.Join(privateTempDir(t), "link")
				if err := os.Symlink(filepath.Dir(input), p); err != nil {
					t.Fatal(err)
				}
				input = filepath.Join(p, filepath.Base(input))
			case "fifo":
				input = filepath.Join(privateTempDir(t), "fifo")
				if err := syscall.Mkfifo(input, 0600); err != nil {
					t.Fatal(err)
				}
			case "permissions":
				if err := os.Chmod(input, 0644); err != nil {
					t.Fatal(err)
				}
			case "directory":
				input = privateTempDir(t)
			case "relative":
				input = "relative.json"
			}
			if _, err := prepareAgentFile(privateTempDir(t), input, "target-model"); err == nil {
				t.Fatal("unsafe input accepted")
			}
		})
	}
	data, _ := agentFilePrepare(t)
	profile := filepath.Join(data, "agent-file.json")
	rawProfile, _ := os.ReadFile(profile)
	if err := os.Remove(profile); err != nil {
		t.Fatal(err)
	}
	elsewhere := agentFileInput(t, rawProfile)
	if err := os.Symlink(elsewhere, profile); err != nil {
		t.Fatal(err)
	}
	if _, _, err := loadAgentFile(data); err == nil {
		t.Fatal("profile symlink accepted")
	}
}

func TestAgentFileFullEnvelopeIdentityAndClaims(t *testing.T) {
	data, summary := agentFilePrepare(t)
	path := filepath.Join(data, "agent-file.json")
	raw, _ := os.ReadFile(path)
	var profile agentFileProfile
	if err := json.Unmarshal(raw, &profile); err != nil {
		t.Fatal(err)
	}
	changed := profile
	changed.TargetModel = "another-target"
	if err := os.WriteFile(path, agentFileJSON(t, changed), 0600); err != nil {
		t.Fatal(err)
	}
	_, other, err := loadAgentFile(data)
	if err != nil || other.Route == summary.Route {
		t.Fatalf("target-only change didn't change identity: %v", err)
	}
	for _, field := range []string{"proof", "examples", "version", "projection"} {
		p := profile
		switch field {
		case "proof":
			p.ProofKind = "package"
		case "examples":
			p.TargetExamples = "passed"
		case "version":
			p.Version = 2
		case "projection":
			p.Projection = json.RawMessage(`{}`)
		}
		if err := os.WriteFile(path, agentFileJSON(t, p), 0600); err != nil {
			t.Fatal(err)
		}
		if _, _, err := loadAgentFile(data); err == nil {
			t.Fatalf("invalid envelope %s accepted", field)
		}
	}
	for _, bad := range [][]byte{append([]byte(`{"unexpected":true,`), raw[1:]...), bytes.Replace(raw, []byte(`"version":`), []byte(`"Version":`), 1), append([]byte(`{"version":1,`), raw[1:]...)} {
		if err := os.WriteFile(path, bad, 0600); err != nil {
			t.Fatal(err)
		}
		if _, _, err := loadAgentFile(data); err == nil {
			t.Fatal("ambiguous envelope accepted")
		}
	}
	if err := os.WriteFile(path, raw, 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(data, "scenario.json"), []byte(v2Marker), 0600); err != nil {
		t.Fatal(err)
	}
	if _, _, err := loadAgentFile(data); err == nil {
		t.Fatal("wrong lineage accepted")
	}
}

func TestAgentFileInvalidCLIProducesNoEvidence(t *testing.T) {
	for _, args := range [][]string{{"agent-file-prepare"}, {"agent-file-inspect"}, {"agent-file-inspect", "--data", "missing"}, {"agent-file-inspect", "extra"}} {
		var out bytes.Buffer
		if err := runCLI(t.Context(), args, &out, io.Discard); err == nil || out.Len() != 0 {
			t.Fatalf("invalid CLI produced evidence: %v", args)
		}
	}
	// The fixed input fixture remains exactly the canonical-parser-produced document.
	raw, p := agentFileFixture(t)
	var roundtrip agentFileProjection
	if err := json.Unmarshal(raw, &roundtrip); err != nil || !reflect.DeepEqual(p, roundtrip) {
		t.Fatal("fixture projection changed")
	}
}
